/// <summary>
/// UPSPricingAttribute of table <c>InventTableModule</c> field ItemId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableModuleItemId extends UPSPricingAttributeInventTableModule implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTableModule, ItemId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);

    InventTableModule   inventTableModule;

    while select ItemId from inventTableModule
        group by ItemId
    {
        if (!ret.in(inventTableModule.ItemId))
        {
            ret.add(inventTableModule.ItemId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTableModule, ItemId));
    qbr.value(queryValue(_value));
}
